    "name" TEXT NOT NULL,
    "name_ar" TEXT,
    "phone" TEXT,
    "email" TEXT,
    "tax_number" TEXT,
    "payment_terms_days" INTEGER NOT NULL DEFAULT 0,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

