-- Hand-written rules -------------------------------------------------------

ALTER TABLE purchasing.supplier
  ADD CONSTRAINT supplier_name_present CHECK (length(btrim(name)) > 0),
  ADD CONSTRAINT supplier_terms_valid CHECK (payment_terms_days BETWEEN 0 AND 365);
CREATE TRIGGER supplier_identity BEFORE DELETE ON purchasing.supplier
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();

-- Only receipts name a supplier.
ALTER TABLE inventory.stock_movement
  ADD CONSTRAINT stock_movement_supplier CHECK (kind = 'receipt' OR supplier_id IS NULL);

ALTER TABLE purchasing.supplier_bill
  ADD CONSTRAINT supplier_bill_invoice_no CHECK (length(btrim(supplier_invoice_no)) > 0),
  ADD CONSTRAINT supplier_bill_dates CHECK (due_date >= bill_date),
  ADD CONSTRAINT supplier_bill_amounts CHECK (
    receipts_value > 0 AND net_amount > 0 AND tax_amount >= 0
    AND variance_amount = net_amount - receipts_value
    AND total = net_amount + tax_amount),
  ADD CONSTRAINT supplier_bill_variance_reason CHECK (variance_amount = 0 OR variance_reason IS NOT NULL),
  ADD CONSTRAINT supplier_bill_tax_shape CHECK ((tax_code IS NULL) = (tax_pct IS NULL) AND (tax_code IS NOT NULL OR tax_amount = 0)),
  ADD CONSTRAINT supplier_bill_cancel_shape CHECK (
    cancelled = (cancel_journal_id IS NOT NULL)
    AND cancelled = (cancel_reason IS NOT NULL)
    AND cancelled = (cancelled_by IS NOT NULL)
    AND cancelled = (cancelled_at IS NOT NULL));

-- The same supplier invoice is entered once (a cancelled bill no longer counts).
CREATE UNIQUE INDEX supplier_bill_invoice_once ON purchasing.supplier_bill (supplier_id, lower(supplier_invoice_no))
  WHERE NOT cancelled;

ALTER TABLE purchasing.supplier_bill_line
  ADD CONSTRAINT supplier_bill_line_amounts CHECK (receipt_value > 0 AND amount > 0);
-- A receipt is charged on one live bill only.
CREATE UNIQUE INDEX supplier_bill_line_receipt_once ON purchasing.supplier_bill_line (movement_id) WHERE live;

ALTER TABLE purchasing.supplier_payment
  ADD CONSTRAINT supplier_payment_method_valid CHECK (method IN ('cash', 'bank')),
  ADD CONSTRAINT supplier_payment_amount_positive CHECK (amount > 0),
  ADD CONSTRAINT supplier_payment_reference CHECK (method = 'cash' OR reference IS NOT NULL);

-- Posted bills never change, except to record their cancellation once (unpaid only).
CREATE OR REPLACE FUNCTION purchasing.guard_supplier_bill() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'supplier_bill_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.cancelled OR NOT NEW.cancelled
     OR (to_jsonb(NEW) - ARRAY['cancelled', 'cancel_journal_id', 'cancel_reason', 'cancelled_by', 'cancelled_at'])
        IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['cancelled', 'cancel_journal_id', 'cancel_reason', 'cancelled_by', 'cancelled_at']) THEN
    RAISE EXCEPTION 'supplier_bill_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM purchasing.supplier_payment p WHERE p.bill_id = OLD.id) THEN
    RAISE EXCEPTION 'supplier_bill_paid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER supplier_bill_guard BEFORE UPDATE OR DELETE ON purchasing.supplier_bill
  FOR EACH ROW EXECUTE FUNCTION purchasing.guard_supplier_bill();

-- Lines are added only to their bill as it is posted (same transaction), for receipts of the same
-- branch and company, from that supplier or with none recorded; the only later change is live → false
-- when the bill is cancelled.
CREATE OR REPLACE FUNCTION purchasing.guard_supplier_bill_line() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  b purchasing.supplier_bill%ROWTYPE;
  m inventory.stock_movement%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'supplier_bill_line_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT * INTO b FROM purchasing.supplier_bill WHERE id = NEW.bill_id;
  IF TG_OP = 'UPDATE' THEN
    IF NOT OLD.live OR NEW.live OR NOT b.cancelled
       OR (to_jsonb(NEW) - 'live') IS DISTINCT FROM (to_jsonb(OLD) - 'live') THEN
      RAISE EXCEPTION 'supplier_bill_line_immutable' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO m FROM inventory.stock_movement WHERE id = NEW.movement_id;
  IF b.id IS NULL OR b.cancelled OR NOT NEW.live
     OR b.xmin <> (pg_current_xact_id()::text::bigint % 4294967296)::text::xid
     OR m.id IS NULL OR m.kind <> 'receipt' OR m.company_id <> b.company_id OR NEW.company_id <> b.company_id
     OR m.branch_id <> b.branch_id OR (m.supplier_id IS NOT NULL AND m.supplier_id <> b.supplier_id)
     OR m.value <> NEW.receipt_value THEN
    RAISE EXCEPTION 'supplier_bill_line_invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER supplier_bill_line_guard BEFORE INSERT OR UPDATE OR DELETE ON purchasing.supplier_bill_line
  FOR EACH ROW EXECUTE FUNCTION purchasing.guard_supplier_bill_line();

-- At commit, a bill's lines add up to its receipts value and billed amount (and it has lines).
CREATE OR REPLACE FUNCTION purchasing.check_supplier_bill_lines() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  rv numeric;
  amt numeric;
BEGIN
  SELECT sum(receipt_value), sum(amount) INTO rv, amt FROM purchasing.supplier_bill_line WHERE bill_id = NEW.id;
  IF rv IS DISTINCT FROM NEW.receipts_value OR amt IS DISTINCT FROM NEW.net_amount THEN
    RAISE EXCEPTION 'supplier_bill_lines_mismatch' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER supplier_bill_lines_add_up AFTER INSERT ON purchasing.supplier_bill
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION purchasing.check_supplier_bill_lines();

-- Payments go to live bills and never exceed what is owed (the bill row is locked).
CREATE OR REPLACE FUNCTION purchasing.guard_supplier_payment() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  b purchasing.supplier_bill%ROWTYPE;
  paid numeric;
BEGIN
  SELECT * INTO b FROM purchasing.supplier_bill WHERE id = NEW.bill_id FOR UPDATE;
  IF b.id IS NULL OR b.cancelled OR b.company_id <> NEW.company_id OR b.branch_id <> NEW.branch_id THEN
    RAISE EXCEPTION 'supplier_payment_bill_invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(sum(amount), 0) INTO paid FROM purchasing.supplier_payment WHERE bill_id = b.id;
  IF paid + NEW.amount > b.total THEN
    RAISE EXCEPTION 'supplier_payment_exceeds_balance' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER supplier_payment_guard BEFORE INSERT ON purchasing.supplier_payment
  FOR EACH ROW EXECUTE FUNCTION purchasing.guard_supplier_payment();
CREATE TRIGGER supplier_payment_immutable BEFORE UPDATE OR DELETE ON purchasing.supplier_payment
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();

-- Permissions for company administrators.
UPDATE iam.role
   SET permissions = (
         SELECT array_agg(DISTINCT p ORDER BY p)
           FROM unnest(permissions || ARRAY['purchasing.read', 'purchasing.manage', 'purchasing.pay']) AS p),
       version = version + 1,
       updated_at = now()
 WHERE is_system AND code = 'company-admin';
